<?php
require_once __DIR__.'/includes/functions.php';
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=$_POST['action']??'';
 if($action==='register'){$name=trim($_POST['full_name']??'');$email=filter_var($_POST['email']??'',FILTER_VALIDATE_EMAIL);$pw=$_POST['password']??'';if(!$name||!$email||strlen($pw)<10){flash('error','Enter your name and email, and use a password of at least 10 characters.');}else{try{$s=db()->prepare('INSERT INTO customer_accounts(full_name,email,password_hash) VALUES(?,?,?)');$s->execute([$name,$email,password_hash($pw,PASSWORD_DEFAULT)]);session_regenerate_id(true);$_SESSION['customer_account_id']=(int)db()->lastInsertId();$_SESSION['customer_name']=$name;header('Location: account.php');exit;}catch(PDOException $e){flash('error','That email already has an account. Please sign in.');}}}
 if($action==='login'){$email=filter_var($_POST['email']??'',FILTER_VALIDATE_EMAIL);$s=db()->prepare('SELECT * FROM customer_accounts WHERE email=?');$s->execute([$email]);$a=$s->fetch();if($a&&password_verify($_POST['password']??'',$a['password_hash'])){session_regenerate_id(true);$_SESSION['customer_account_id']=(int)$a['id'];$_SESSION['customer_name']=$a['full_name'];header('Location: account.php');exit;}flash('error','Email or password is incorrect.');}
 if($action==='logout'){unset($_SESSION['customer_account_id'],$_SESSION['customer_name']);session_regenerate_id(true);header('Location: account.php');exit;}
 if($action==='update-profile'&&customer_id()){$name=trim($_POST['full_name']??'');if($name===''){flash('error','Enter your name.');}else{db()->prepare('UPDATE customer_accounts SET full_name=? WHERE id=?')->execute([$name,customer_id()]);$_SESSION['customer_name']=$name;flash('success','Profile updated.');header('Location: account.php');exit;}}
}
$page_title='My account';require 'includes/header.php';
if(customer_id()):
 $aid=customer_id();$s=db()->prepare('SELECT full_name,email FROM customer_accounts WHERE id=?');$s->execute([$aid]);$account=$s->fetch();
 $o=db()->prepare('SELECT o.*, (SELECT GROUP_CONCAT(CONCAT(oi.product_name," × ",oi.quantity) SEPARATOR ", ") FROM order_items oi WHERE oi.order_id=o.id) items FROM orders o JOIN customers c ON c.id=o.customer_id WHERE c.email=? ORDER BY o.created_at DESC');$o->execute([$account['email']]);$orders=$o->fetchAll();
 $w=db()->prepare('SELECT p.id,p.name,p.brand,p.price,(SELECT image_path FROM product_images WHERE product_id=p.id ORDER BY id LIMIT 1) image FROM wishlist_items wi JOIN products p ON p.id=wi.product_id WHERE wi.account_id=?');$w->execute([$aid]);$wishlist=$w->fetchAll();
 $recent=db()->prepare('SELECT p.id,p.name,p.brand,p.price,(SELECT image_path FROM product_images WHERE product_id=p.id ORDER BY id LIMIT 1) image FROM recently_viewed rv JOIN products p ON p.id=rv.product_id WHERE rv.account_id=? ORDER BY rv.viewed_at DESC LIMIT 3');$recent->execute([$aid]);$recent=$recent->fetchAll();
?>
<section class="section"><div class="container"><p class="eyebrow">Your Collins M account</p><h1>Welcome, <?=e($account['full_name'])?></h1><div class="account-grid"><section class="admin-panel"><h2>My orders &amp; tracking</h2><?php if(!$orders):?><p>No orders are linked to this email yet.</p><?php else:foreach($orders as $order):$stages=['Pending','Processing','Shipped','Out for Delivery','Delivered'];$idx=array_search($order['status'],$stages,true);if($order['status']==='Confirmed'||$order['status']==='Ready for Delivery')$idx=1;if($order['status']==='Completed')$idx=4;?><article class="account-order"><div><strong><?=e($order['order_number'])?></strong> · <?=e($order['created_at'])?></div><p><?=e($order['items']??'')?></p><p><?=money($order['total'])?> · <?=e($order['status'])?><?php if($order['estimated_delivery']):?> · ETA <?=e($order['estimated_delivery'])?><?php endif?></p><?php if($idx!==false):?><div class="order-progress" aria-label="Order progress"><span style="--progress:<?=((int)$idx/4)*100?>%"></span></div><small>Placed　 Processing　 Shipped　 Out for delivery　 Delivered</small><?php endif?></article><?php endforeach;endif?></section>
<section class="admin-panel"><h2>My profile</h2><form method="post" class="settings-form"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="update-profile"><label>Full name<input name="full_name" required maxlength="120" value="<?=e($account['full_name'])?>"></label><label>Email (used to match your orders)<input type="email" value="<?=e($account['email'])?>" disabled></label><button class="button primary">Save profile</button></form><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><button class="button dark-button" name="action" value="logout">Sign out</button></form></section>
<section class="admin-panel"><h2>Wishlist</h2><?php if(!$wishlist):?><p>No saved products yet.</p><?php else:?><div class="mini-products"><?php foreach($wishlist as $p):?><a href="product-details.php?id=<?=$p['id']?>"><img src="<?=image_url($p['image'])?>" alt=""><span><?=e($p['name'])?><br><?=money($p['price'])?></span></a><?php endforeach?></div><?php endif?></section>
<section class="admin-panel"><h2>Recently viewed</h2><?php if(!$recent):?><p>Product pages you visit will appear here.</p><?php else:?><div class="mini-products"><?php foreach($recent as $p):?><a href="product-details.php?id=<?=$p['id']?>"><img src="<?=image_url($p['image'])?>" alt=""><span><?=e($p['name'])?><br><?=money($p['price'])?></span></a><?php endforeach?></div><?php endif?></section></div></div></section>
<?php else: ?>
<section class="section"><div class="container account-grid"><div class="auth-card"><p class="eyebrow">Welcome back</p><h1>Sign in</h1><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="login"><label>Email<input required type="email" name="email"></label><label>Password<input required type="password" name="password"></label><button class="button primary">Sign in</button></form><p><a href="forgot-password.php">Forgot your password?</a></p></div><div class="auth-card"><p class="eyebrow">New to Collins M?</p><h2>Create an account</h2><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="register"><label>Full name<input required name="full_name" maxlength="120"></label><label>Email<input required type="email" name="email" maxlength="190"></label><label>Password<input required type="password" name="password" minlength="10"></label><button class="button primary">Create account</button></form></div></div></section>
<?php endif;require 'includes/footer.php';
